			background-color: black;
			border-bottom-left-radius: 5px;
			border-bottom-right-radius: 5px
		]])

		--Consoles where the text is placed
		ataxiagui.Chat[sec.."center"] = Geyser.MiniConsole:new({
			name = "ataxiagui.Chat."..sec.."center",
			x = "1%", y = "1%",
			width = "98%", height = "98%",
			color = "black"
